using System;
using System.Collections.Generic;
using NUnit.Framework;
using Spacewars.Simulation;
using Spacewars.Runtime;
namespace Spacewars.Tests.EditMode
{
    public sealed partial class NavigationPhysicalBodyTests
    {
        [TestCase(1,false)][TestCase(65,false)][TestCase(129,true)]
        public void BodyArrivalSourceOrderBackingsSelectorsAndLargeCandidateList(int count,bool qualified)
        {
            var hot=new NavigationRetentionBudget();Assert.True(hot.TryOpenScope(NavigationPreparationKind.Admission,1,1,out var birth));var r=birth.OwnedReservation();var provider=LayeredNavigationProvider.CopyOwned((LayeredNavigationProvider)NavigationAdmission.CertifiedFlatProvider(new NavGeometry(100,new NavObstacle[0],1)),r);var values=new NavLocation[count];for(int n=0;n<count;n++)values[n]=qualified&&n%2==0?provider.Surfaces[0].OwnedLocation(new NavPoint(n*.25,0)):new NavLocation(new NavPoint(n*.25,0),NavLocation.FlatSurface);var requested=qualified?provider.Surfaces[0].OwnedLocation(new NavPoint(-1,0)):new NavLocation(new NavPoint(-1,0),NavLocation.FlatSurface);
            var source=new NavArrivalCandidateSource("source",3,requested,values);var value=NavArrivalCandidateSource.CopyOwned(source,r);string key=source.StableKey;Assert.AreEqual(key,value.StableKey);Assert.AreNotSame(source.StableKey,value.StableKey);Assert.AreNotSame(source.Id,value.Id);byte[] sourceBytes=CaptureGraph(hot,value.StorageRoot);var root=NavRetainedArray<NavOwnedStorage>.Copy(new[]{value.StorageRoot,provider.StorageRoot},birth.TryReserve);value.StorageRoot.ReleaseOwner();provider.StorageRoot.ReleaseOwner();birth.Attach(root);birth.Commit(root,_=>{});var bytes=CaptureGraph(hot,root);long charge=Unique(root);Assert.AreEqual(charge,hot.PhysicalBytes);root.Release();root=null;value=null;source=null;provider=null;values=null;Assert.Zero(hot.PhysicalBytes);
            var cold=new NavigationRetentionBudget();Assert.True(cold.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var decode));var restored=(NavRetainedArray<NavOwnedStorage>)Decode(bytes,decode.OwnedReservation());decode.Attach(restored);decode.Commit(restored,_=>{});var s=(NavArrivalCandidateSource)((NavDeclarationStorage)restored[0]).Facade;var p=(LayeredNavigationProvider)((NavDeclarationStorage)restored[1]).Facade;Assert.AreEqual(key,s.StableKey);Assert.AreEqual(count,s.Candidates.Count);Assert.AreEqual(3,s.Revision);Assert.AreEqual("source",s.Id);Assert.AreSame(qualified?p.Surfaces[0].StorageRoot:s.StorageRoot,s.Requested.NameReference.Owner);
            var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;var priv=(NavLocation[])typeof(NavArrivalCandidateSource).GetField("candidates",flags).GetValue(s);var pub=(NavLocation[])typeof(NavArrivalCandidateSource).GetField("publicCandidates",flags).GetValue(s);Assert.AreNotSame(priv,pub);for(int n=0;n<count;n++){Assert.AreEqual(n*.25,s.Candidates[n].Position.X);Assert.AreSame(priv[n].SurfaceId,pub[n].SurfaceId);bool external=qualified&&n%2==0;Assert.AreSame(external?p.Surfaces[0].StorageRoot:s.StorageRoot,s.Candidates[n].NameReference.Owner);Assert.AreEqual(external?NavNameRole.SurfaceId:NavNameRole.ArrivalSourceCandidateSurface,s.Candidates[n].NameReference.Role);Assert.AreEqual(external?-1:n,s.Candidates[n].NameReference.Index);}Assert.AreEqual(charge,cold.PhysicalBytes);CollectionAssert.AreEqual(bytes,CaptureGraph(cold,restored));
            NavArrivalCandidateSource Born(INavStorageReservation reservation)=>NavArrivalCandidateSource.CopyOwned(s,reservation);Assert.True(cold.TryOpenScope(NavigationPreparationKind.Admission,1,20,out var trialBirth));var counter=new Refusal(trialBirth,int.MaxValue);var copied=Born(counter);Assert.AreEqual(key,copied.StableKey);for(int n=0;n<count;n++)Assert.AreSame(s.Candidates[n].NameReference.Owner,copied.Candidates[n].NameReference.Owner);trialBirth.Attach(copied.StorageRoot);int calls=counter.Calls;trialBirth.Discard();Assert.AreEqual(charge,cold.PhysicalBytes);
            for(int nth=1;nth<=calls;nth++){Assert.True(cold.TryOpenScope(NavigationPreparationKind.Admission,1,20+nth,out var rejection));var refusal=new Refusal(rejection,nth);Assert.Throws<InvalidOperationException>(()=>Born(refusal));Assert.AreEqual(nth,refusal.Calls);rejection.Discard();Assert.AreEqual(charge,cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);CollectionAssert.AreEqual(bytes,CaptureGraph(cold,restored));}
            var foreign=new NavigationRetentionBudget();Assert.True(foreign.TryOpenScope(NavigationPreparationKind.Admission,1,1,out var rejected));Assert.Throws<ArgumentException>(()=>Born(rejected.OwnedReservation()));Assert.Zero(foreign.PhysicalBytes);Assert.AreEqual(NavigationRetentionBudget.ScopeBytes,foreign.HeldBytes);rejected.Discard();restored.Release();restored=null;s=null;p=null;priv=null;pub=null;Assert.Zero(cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);
            for(int fault=0;fault<4;fault++){byte[] malformed=(byte[])sourceBytes.Clone();if(fault<2)Buffer.BlockCopy(BitConverter.GetBytes(fault==0?0:-1),0,malformed,21,4);else if(fault==2)malformed[25]=2;else{malformed[malformed.Length-2]=255;malformed[malformed.Length-1]=255;}var bad=new NavigationRetentionBudget();Assert.True(bad.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var rejection));Assert.Throws<ArgumentException>(()=>Decode(malformed,rejection.OwnedReservation()));rejection.Discard();Assert.Zero(bad.PhysicalBytes);Assert.Zero(bad.HeldBytes);Assert.Zero(bad.ActiveScopes);}
            var counted=new NavigationRetentionBudget();Assert.True(counted.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var scope));var all=new Refusal(scope,int.MaxValue);var trial=Decode(bytes,all);scope.Attach(trial);int allocations=all.Calls;scope.Discard();Assert.Zero(counted.PhysicalBytes);
            for(int nth=1;nth<=allocations;nth++){var bad=new NavigationRetentionBudget();Assert.True(bad.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var rejection));var refusal=new Refusal(rejection,nth);Assert.Throws<InvalidOperationException>(()=>Decode(bytes,refusal));Assert.AreEqual(nth,refusal.Calls);rejection.Discard();Assert.Zero(bad.PhysicalBytes);Assert.Zero(bad.HeldBytes);Assert.Zero(bad.ActiveScopes);}
        }
    }
